const D = { energy:.6, scale:1, density:.5, speed:1, hue:198, x:.5, y:.5, lamps:.5, style:'steel', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, HU = ((P.hue%360)+360)%360;
const wire = (sty === 'blueprint'), rust = (sty === 'rust'), therm = (sty === 'thermal');

// ---- the camera DESCENDS the shaft; catwalks rise through the frame forever
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z = (S.z||0) + dt * P.speed * (.10 + .12*K.intensity + .11*P.energy);
const bsm = (S.bm = (S.bm||0)*.84 + (A.bass||0)*.16);
const gl = (.44 + .56*P.energy) * (.55 + .5*K.intensity) + bsm*.26;

const dA = .55*Math.sin(K.t*.41) + .30*Math.sin(K.t*.97+1.7) + .17*Math.sin(K.t*1.63+.4);
const dB = .50*Math.sin(K.t*.53+2.1) + .32*Math.sin(K.t*1.19+.9) + .20*Math.sin(K.t*2.29+2.6);
const dC = .60*Math.sin(K.t*.089) + .40*Math.sin(K.t*.211+1.1);

const LEV = u*.52*P.scale;                       // level pitch; Z distances stay FIXED
const CW = u*.30*P.scale, RH = u*.26*P.scale, DT = u*.028*P.scale;
const XW = u*2.6, ZW = u*4.2;                    // the volume
const NL = 4 + Math.round(cl(P.density,0,1)*5);  // levels either side of the eye

const camY = S.z*LEV;
const camX = u*.10*dB*P.energy, camZ = u*.09*dC*P.energy;
// a real look-around: the yaw wanders on incommensurate rates and never returns
const yaw = .30*Math.sin(K.t*.037) + .13*Math.sin(K.t*.091+1.3) + .05*dA*P.energy;
const ca = Math.cos(yaw), sa = Math.sin(yaw);
const f = u*1.05, NEAR = u*.10;
const vcx = cl(P.x,.15,.85)*width, vcy = cl(P.y,.25,.78)*height;
const lc = Math.floor(S.z);

// a work light swings somewhere in the void, on its own slow clock
const ly0 = S.z + 1.4 + 2.1*Math.sin(K.t*.059) + .9*Math.sin(K.t*.137+2.2);

// ---- projection ---------------------------------------------------------------
const AXa = new Float64Array(10), AYa = new Float64Array(10), AZa = new Float64Array(10);
const BXa = new Float64Array(14), BYa = new Float64Array(14);
function poly(v){
  const n = v.length/3;
  for (let i=0;i<n;i++){
    const X = v[i*3]-camX, Y = v[i*3+1]-camY, Z = v[i*3+2]-camZ;
    AXa[i] = X*ca - Z*sa; AYa[i] = Y; AZa[i] = X*sa + Z*ca;
  }
  let m = 0;
  for (let i=0;i<n;i++){
    const j = (i+1)%n, az = AZa[i], bz = AZa[j], ai = az>NEAR, bi2 = bz>NEAR;
    if (ai){ BXa[m] = vcx + f*AXa[i]/az; BYa[m] = vcy + f*AYa[i]/az; m++; }
    if (ai !== bi2){
      const tt = (NEAR-az)/(bz-az);
      BXa[m] = vcx + f*(AXa[i]+(AXa[j]-AXa[i])*tt)/NEAR;
      BYa[m] = vcy + f*(AYa[i]+(AYa[j]-AYa[i])*tt)/NEAR; m++;
    }
  }
  if (m < 3) return false;
  beginShape(); for (let i=0;i<m;i++) vertex(BXa[i], BYa[i]); endShape(CLOSE);
  return true;
}
function pt2(X,Y,Z){
  const dx = X-camX, dy = Y-camY, dz = Z-camZ;
  const rz = dx*sa + dz*ca;
  if (rz <= NEAR) return null;
  return [vcx + f*(dx*ca - dz*sa)/rz, vcy + f*dy/rz, rz];
}

// ---- tone tables ---------------------------------------------------------------
function mixc(c,d,t){ const dh = ((d[0]-c[0])%360+540)%360-180;
  return [c[0]+dh*t, c[1]+(d[1]-c[1])*t, c[2]+(d[2]-c[2])*t]; }
const HAZE = wire ? [212, 58, 20] : rust ? [20, 40, 22] : therm ? [252, 60, 10]
           : sty === 'sodium' ? [30, 44, 20] : [(HU+4)%360, 22, 22];
const fogA = wire ? .28 : .76;
function tone(v, tv){
  if (wire)  return [212, 60, cl(11 + 11*v, 7, 32)];
  if (therm) return [cl(258 - 240*v, 10, 262), cl(66 - 16*v, 20, 80), cl(8 + 82*v, 4, 96)];
  if (rust)  return [cl(16 + 18*tv - 5*v, 4, 42), cl(34 + 30*tv - 12*v, 6, 64), cl(6 + 76*v, 4, 92)];
  if (sty === 'sodium') return [cl(28 + 10*tv, 18, 44), cl(54 - 22*v, 8, 68), cl(4 + 76*v, 3, 92)];
  return [(HU - 8 + 10*tv + 360)%360, cl(20 - 11*v + 6*tv, 2, 30), cl(7 + 78*v, 4, 95)];
}
function ink(a){ if (wire) stroke(190, 30, 100, a); else stroke((HU+2)%360, 12, 84, a*.30); }
const RY = [1, .58, .10], RG = [.055, .05, .075];
const LTH = sty === 'sodium' ? 32 : rust ? 34 : therm ? 24 : (HU-160+360)%360;

// ---- the volume: light from above dying into the deep (banded) --------------------
noStroke();
const NBD = 32;
for (let i=0;i<NBD;i++){
  const s = i/(NBD-1);
  const c = tone(cl(.34*Math.pow(1-s, 1.6) + .06, 0, 1), fr(i*3.1));
  fill(c[0], c[1], cl(c[2] + (fr(i*5.7)-.5)*1.7, 0, 100));
  rect(0, s*height - 1.5, width, height/NBD + 3);
}

// ---- far wall: corrugated steel ribs — texture, never a flat fill -----------------
{
  const NRB = 22;
  for (let i=0; i<NRB; i++){
    const x0 = -XW + (2*XW)*(i/NRB), x1 = -XW + (2*XW)*((i+1)/NRB);
    const rv = (.16 + .13*Math.abs(Math.cos(i*1.9))) * (.5+.5*gl);
    const c = mixc(tone(cl(rv,0,1), fr(i*7.3)), HAZE, .62*fogA);
    if (wire){ noFill(); ink(34); } else { noStroke(); fill(c[0], c[1], c[2], 100); }
    poly([x0, camY-LEV*8, ZW, x1, camY-LEV*8, ZW, x1, camY+LEV*8, ZW, x0, camY+LEV*8, ZW]);
  }
}

// ---- full-height stanchions tying the levels together ----------------------------
for (let i=0;i<5;i++){
  const cx2 = -XW*.55 + fr(i*7.7+3)*XW*1.1, cz2 = u*1.9 + fr(i*13.3+9)*(ZW - u*2.4);
  const p = pt2(cx2, camY, cz2);
  if (!p) continue;
  if (p[0] < -u*.1 || p[0] > width + u*.1) continue;
  const hz = cl(p[2]/(ZW*.9), 0, 1);
  const rw = Math.max(1.2, f*(u*.026)/p[2]);
  const NSf = cl(Math.round(rw/(u*.008)), 1, 5);
  for (let s2=0; s2<NSf; s2++){
    const p0 = -1 + 2*s2/NSf, p1 = -1 + 2*(s2+1)/NSf, pm = (p0+p1)*.5;
    const lamb = cl(.20 + .84*Math.cos((pm - .45)*1.45), 0, 1);
    let c = mixc(tone(cl(lamb*(.34+.42*gl), 0, 1), fr(i*3.1)), HAZE, hz*fogA);
    if (rust) c = mixc(c, [14, 62, 30], fr(i*11.1)*.5);
    if (wire){ noFill(); ink(44); } else { noStroke(); fill(c[0], c[1], c[2], 100); }
    rect(p[0] + p0*rw, 0, (p1-p0)*rw + 1.1, height);
  }
}

// ---- gather the catwalks, depth-sort, paint far -> near ----------------------------
const decks = [];
for (let j = lc-NL; j <= lc+NL; j++){
  const nHere = fr(j*3.7) < .30 ? 2 : 1;
  for (let c2=0; c2<nHere; c2++){
    const r0 = fr(j*13.1 + c2*29.3);
    const alongX = fr(j*5.9 + c2*17.7) < .6;
    const zc = u*.85 + r0*(ZW - u*1.5);
    const xc = -XW*.45 + fr(j*11.3 + c2*7.1)*XW*.9;
    const Y = j*LEV;
    const p = pt2(alongX ? 0 : xc, Y, alongX ? zc : u*1.9);
    if (!p) continue;
    decks.push([p[2], j, c2, alongX, zc, xc, Y]);
  }
}
decks.sort((a,b) => b[0]-a[0]);
const ND = Math.min(decks.length, 11);

strokeWeight(Math.max(1, u*.0014));
for (let q = decks.length-ND; q < decks.length; q++){
  const dd = decks[q], rz = dd[0], j = dd[1], alongX = dd[3], zc = dd[4], xc = dd[5], Y = dd[6];
  const hz = cl(rz/(ZW*.9), 0, 1);
  const tv = fr(j*31.7 + dd[2]*3.3);
  const lit = cl(.34 + .58*Math.exp(-Math.pow(j - ly0, 2)*.30), 0, 1);
  const below = (Y > camY);                       // below the eye => we read the grating
  const rr = fr(j*19.1);

  // run endpoints
  const aA = alongX ? -XW*.8 : u*.9, aB = alongX ? XW*.8 : ZW - u*.35;
  const gA = (t2) => alongX ? [aA + (aB-aA)*t2, zc] : [xc, aA + (aB-aA)*t2];
  const wA = CW*.5;
  const e0 = gA(0), e1 = gA(1);
  const nx = alongX ? 0 : 1, nz = alongX ? 1 : 0;   // deck half-width direction

  // ---- deck: drawn translucent so it reads as open grating, then slatted
  const dv = (below ? (.24 + .30*lit) : (.09 + .10*lit)) * (.5+.55*gl) + .06*tv;
  let c = mixc(tone(cl(dv,0,1), tv), HAZE, hz*fogA);
  if (rust) c = mixc(c, [14, 62, 30], rr*.5);
  if (wire){ noFill(); ink(48); } else { noStroke(); fill(c[0], c[1], c[2], below ? 84 : 100); }
  poly([e0[0]-nx*wA, Y, e0[1]-nz*wA, e1[0]-nx*wA, Y, e1[1]-nz*wA,
        e1[0]+nx*wA, Y, e1[1]+nz*wA, e0[0]+nx*wA, Y, e0[1]+nz*wA]);
  if (below && !wire && hz < .55){
    ink(30); noFill();
    for (let s2=1; s2<8; s2++){
      const t2 = s2/8, g2 = gA(t2);
      poly([g2[0]-nx*wA, Y, g2[1]-nz*wA, g2[0]+nx*wA, Y, g2[1]+nz*wA]);
    }
  }
  // ---- edge fascia / stringer beam
  if (!wire){
    const c2 = mixc(tone(cl(dv*.55 + .05, 0, 1), tv), HAZE, hz*fogA);
    noStroke(); fill(c2[0], c2[1], c2[2], 100);
    for (let sg=-1; sg<=1; sg+=2){
      poly([e0[0]+nx*wA*sg, Y, e0[1]+nz*wA*sg, e1[0]+nx*wA*sg, Y, e1[1]+nz*wA*sg,
            e1[0]+nx*wA*sg, Y+DT, e1[1]+nz*wA*sg, e0[0]+nx*wA*sg, Y+DT, e0[1]+nz*wA*sg]);
    }
  }
  // ---- handrails: two bands + a toe board, both sides
  for (let sg=-1; sg<=1; sg+=2){
    for (let ri=0; ri<3; ri++){
      const yy = Y - RH*RY[ri], hgt = RH*RG[ri];
      const rv = (ri===2 ? .16 : .34 + .30*lit) * (.5+.55*gl);
      let rc = mixc(tone(cl(rv,0,1), tv), HAZE, hz*fogA);
      if (rust) rc = mixc(rc, [12, 66, 30], rr*.6);
      if (wire){ noFill(); ink(52); } else { noStroke(); fill(rc[0], rc[1], rc[2], 100); }
      poly([e0[0]+nx*wA*sg, yy, e0[1]+nz*wA*sg, e1[0]+nx*wA*sg, yy, e1[1]+nz*wA*sg,
            e1[0]+nx*wA*sg, yy+hgt, e1[1]+nz*wA*sg, e0[0]+nx*wA*sg, yy+hgt, e0[1]+nz*wA*sg]);
    }
    // stanchions
    for (let s2=0; s2<4; s2++){
      const g2 = gA((s2+.5)/4);
      const p = pt2(g2[0]+nx*wA*sg, Y, g2[1]+nz*wA*sg);
      if (!p) continue;
      const rw = Math.max(.9, f*(u*.008)/p[2]);
      const yb = vcy + f*(Y - camY)/p[2], yt = vcy + f*(Y - RH - camY)/p[2];
      let sc = mixc(tone(cl((.26 + .26*lit)*(.5+.55*gl), 0, 1), tv), HAZE, hz*fogA);
      if (wire){ noFill(); ink(46); } else { noStroke(); fill(sc[0], sc[1], sc[2], 100); }
      rect(p[0] - rw*.5, Math.min(yb,yt), rw, Math.abs(yb-yt));
    }
  }
  // ---- a clamped work lamp, seeded, with a bloom and a pool on the deck
  if (!wire && fr(j*23.1 + dd[2]*5.3) < cl(P.lamps,0,1)*.8){
    const g2 = gA(.28 + .44*fr(j*9.7));
    const p = pt2(g2[0], Y - RH*1.02, g2[1]);
    if (p){
      const fl = .62 + .38*Math.sin(K.t*(.5 + fr(j*2.7)*.6) + j*2.1);
      push(); blendMode(ADD); noStroke();
      for (let i=4;i>=1;i--){
        fill(LTH, therm?70:24, 100, cl(2.2 + 4.6*gl*fl, 0, 15));
        ellipse(p[0], p[1], f*(u*.30)/p[2]*i*.45, f*(u*.30)/p[2]*i*.45);
      }
      pop(); blendMode(BLEND);
      noStroke(); fill(LTH, therm?60:14, cl(66 + 30*gl*fl, 10, 98), 100);
      const rw = Math.max(1.4, f*(u*.014)/p[2]);
      ellipse(p[0], p[1], rw*2, rw*2);
    }
  }
}

// ---- the shaft of light from above (partial frame, ADD, no flash) ------------------
if (!wire){
  push(); blendMode(ADD); noStroke();
  const sx2 = vcx + u*.30*Math.sin(K.t*.043) + u*.12*Math.sin(K.t*.107+1.7);
  for (let i=5;i>=1;i--){
    fill(LTH, therm?60:20, 100, 1.5 + 2.8*gl);
    quad(sx2 - u*.05*i, 0, sx2 + u*.05*i, 0, sx2 + u*.17*i, height, sx2 - u*.17*i, height);
  }
  pop(); blendMode(BLEND);
}

// ---- cached grain + vignette --------------------------------------------------------
if (!S.gv || S.gk !== width+'x'+height+'|'+sty){
  const g = createGraphics(width, height); g.colorMode(HSB,360,100,100,100); g.noStroke();
  const N = Math.min(9000, Math.floor(width*height/230));
  for (let i=0;i<N;i++){
    const px = Math.abs((Math.sin(i*12.9898)*43758.5453)%1)*width;
    const py = Math.abs((Math.sin(i*78.233+2.1)*43758.5453)%1)*height;
    g.fill(0,0, (i%2) ? 100 : 0, 6);
    g.rect(px, py, 1.7, 1.7);
  }
  for (let i=0;i<26;i++){ const s=i/26, bw=(1-s)*.10;
    g.fill(0,0,0, 1.2 + 4.2*s*s);
    g.rect(0,0,width,height*bw); g.rect(0,height*(1-bw),width,height*bw);
    g.rect(0,0,width*bw,height); g.rect(width*(1-bw),0,width*bw,height);
  }
  S.gv = g; S.gk = width+'x'+height+'|'+sty;
}
image(S.gv, 0, 0);
if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
